mapper.select:
-- 동일 요청만 재사용하며 다른 source의 응답은 service에서 반환하지 않는다.
SELECT 
FROM announcement_attachment_jobs j WHERE j.idempotency_key = #{idempotencyKey}

-- 내부 worker의 고정 작업 식별자를 조회한다. API 노출에는 source/권한 확인이 별도 필요하다.
SELECT 
FROM announcement_attachment_jobs j WHERE j.id = #{jobId}

mapper.delete:
-- 오래된 worker가 새 소유자의 슬롯을 해제하지 못하도록 세 token을 모두 검사한다.
DELETE FROM announcement_attachment_resource_leases
WHERE resource_lease_token = #{resourceLeaseToken} AND job_id = #{jobId} AND job_lease_token = #{jobLeaseToken}
